//! A `<pre>` whose one-line form overflows wrapped its attributes where the
//! oracle keeps them flat and breaks inside the content (#4174). prettier lays
//! the attribute group out flat when everything up to the first line-break
//! opportunity fits — its `fits` runs past `>` into the content, where
//! `printPre` offers a break at a text newline, at a mustache's first breakable
//! JS group, or at a child tag's own attribute / hug break — and only a content
//! with none of those charges the close tag too. The mustaches on the content
//! line are then laid out left to right, each charged what precedes it on its
//! first line and what follows it on its last.
//!
//! Every expectation here was generated by running the input through the
//! oxfmt(`svelte: true`) oracle. Both directions are in the table: `prism`,
//! `ident_no_break` and `text_newline_overflow` overflow before any opportunity
//! and wrap their attributes; `text_newline_fits` and `prism_plain` must not
//! move at all.

use rsvelte_formatter::{
    FormatOptions, IndentStyle, IndentWidth, JsFormatOptions, LineWidth, format,
};

fn fmt(src: &str) -> String {
    let js = JsFormatOptions {
        indent_style: IndentStyle::Space,
        indent_width: IndentWidth::try_from(2u8).unwrap(),
        line_width: LineWidth::try_from(80u16).unwrap(),
        ..JsFormatOptions::default()
    };
    let options = FormatOptions {
        js,
        typescript: false,
        ..FormatOptions::new()
    };
    format(src, &options).expect("format ok")
}

