#[test]
fn every_cell_formats_to_the_oracle_output() {
    let mut wrong = Vec::new();
    for (name, input, expected) in CELLS {
        let got = fmt(input);
        if got != *expected {
            wrong.push(format!("{name}: got {got:?}, want {expected:?}"));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

fn pre_open_line(text: &str) -> &str {
    text.lines()
        .find(|l| l.trim_start().starts_with("<pre"))
        .expect("a <pre> line")
}

/// Liveness: the table has to carry a `<pre>` whose attributes stay flat while
/// its content breaks, one whose attributes wrap, and one the formatter leaves
/// untouched, or it measures one direction of the rule.
#[test]
fn the_table_carries_every_direction() {
    let flat_content_breaks = CELLS.iter().filter(|(_, input, want)| {
        let open = pre_open_line(want);
        open.contains('>') && want.lines().count() > input.lines().count()
    });
    let attrs_wrap = CELLS
        .iter()
        .filter(|(_, _, want)| pre_open_line(want).trim() == "<pre");
    let untouched = CELLS.iter().filter(|(_, input, want)| input == want);
    assert!(
        flat_content_breaks.count() >= 3,
        "no cell keeps its attributes flat and breaks its content"
    );
    assert!(attrs_wrap.count() >= 3, "no cell wraps its attributes");
    assert!(untouched.count() >= 2, "no cell is left untouched");
}

#[test]
fn the_oracle_output_is_a_fixed_point() {
    for (name, _, expected) in CELLS {
        assert_eq!(fmt(expected), *expected, "{name}: the oracle form moved");
    }
}
